namespace InventoryApp.Services;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift A", Location = "Warehouse 1", LastInspected = new DateTime(2026, 5, 12) },
            new() { Id = 2, Name = "Conveyor Belt B", Location = "Warehouse 2", LastInspected = new DateTime(2026, 6, 3) },
            new() { Id = 3, Name = "Hydraulic Press", Location = "Factory Floor", LastInspected = new DateTime(2026, 4, 20) },
            new() { Id = 4, Name = "CNC Lathe", Location = "Machine Shop", LastInspected = new DateTime(2026, 6, 28) },
            new() { Id = 5, Name = "Welding Robot", Location = "Assembly Line", LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 6, Name = "Air Compressor", Location = "Utility Room", LastInspected = new DateTime(2026, 5, 30) },
            new() { Id = 7, Name = "Overhead Crane", Location = "Loading Dock", LastInspected = new DateTime(2026, 6, 10) },
            new() { Id = 8, Name = "Pallet Jack", Location = "Warehouse 1", LastInspected = new DateTime(2026, 2, 22) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering]
@using InventoryApp.Services
@inject EquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (equipment == null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? equipment;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        _subscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("equipment", out var restored))
        {
            // Interactive render: reuse data persisted during prerender (no second service call)
            equipment = restored;
        }
        else
        {
            // Prerender/streaming: fetch from service (only call)
            equipment = await EquipmentService.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("equipment", equipment);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

